// Dashboard page - the main page after login
// Shows: summary cards, charts, add transaction form, recent transactions

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
  PieChart, Pie, Cell, Tooltip, Legend,
  BarChart, Bar, XAxis, YAxis, CartesianGrid, ResponsiveContainer
} from 'recharts';
import TransactionForm from '../components/TransactionForm';
import TransactionList from '../components/TransactionList';
import Navbar from '../components/Navbar';
import './Dashboard.css';

// Colors for the pie chart slices
const PIE_COLORS = ['#4caf50', '#f44336', '#2196f3', '#ff9800', '#9c27b0', '#00bcd4'];

function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [csvLoading, setCsvLoading] = useState(false);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchTransactions();
  }, []);

  const fetchTransactions = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/transactions', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(response.data);
    } catch (error) {
      console.log('Error fetching transactions:', error.message);
    }
  };

  const handleTransactionAdded = () => {
    fetchTransactions();
    setShowForm(false);
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/transactions/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(transactions.filter(t => t.id !== id));
    } catch (error) {
      console.log('Error deleting transaction:', error.message);
    }
  };

  // Download CSV - we call the backend which returns a CSV file
  const handleExportCSV = async () => {
    setCsvLoading(true);
    try {
      const response = await axios.get('http://localhost:5000/api/transactions/export/csv', {
        headers: { Authorization: `Bearer ${token}` },
        responseType: 'blob'  // important: tells axios to treat response as a file
      });

      // Create a download link and click it automatically
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', 'transactions.csv');
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (error) {
      console.log('CSV export error:', error.message);
      alert('No transactions to export or export failed.');
    }
    setCsvLoading(false);
  };

  // Calculate totals
  const totalIncome = transactions
    .filter(t => t.type === 'income')
    .reduce((sum, t) => sum + parseFloat(t.amount), 0);

  const totalExpense = transactions
    .filter(t => t.type === 'expense')
    .reduce((sum, t) => sum + parseFloat(t.amount), 0);

  const balance = totalIncome - totalExpense;

  // --- Chart Data ---

  // Pie chart: expense breakdown by category
  const expenseByCategory = {};
  transactions
    .filter(t => t.type === 'expense')
    .forEach(t => {
      expenseByCategory[t.category] = (expenseByCategory[t.category] || 0) + parseFloat(t.amount);
    });

  const pieData = Object.keys(expenseByCategory).map(cat => ({
    name: cat,
    value: parseFloat(expenseByCategory[cat].toFixed(2))
  }));

  // Bar chart: monthly income vs expense
  // Group transactions by month
  const monthlyData = {};
  transactions.forEach(t => {
    const month = t.date ? t.date.substring(0, 7) : 'Unknown';  // "2024-05"
    if (!monthlyData[month]) {
      monthlyData[month] = { month, income: 0, expense: 0 };
    }
    if (t.type === 'income') {
      monthlyData[month].income += parseFloat(t.amount);
    } else {
      monthlyData[month].expense += parseFloat(t.amount);
    }
  });

  // Sort by month and take last 6 months
  const barData = Object.values(monthlyData)
    .sort((a, b) => a.month.localeCompare(b.month))
    .slice(-6);

  const recentTransactions = transactions.slice(0, 5);

  return (
    <div>
      <Navbar />
      <div className="dashboard-container">

        {/* Page Heading */}
        <div className="dashboard-heading">
          <h2>Finance Dashboard</h2>
          <p>Track your income and expenses easily</p>
        </div>

        {/* Summary Cards */}
        <div className="summary-cards">
          <div className="card income-card">
            <h3>Total Income</h3>
            <p>₹ {totalIncome.toFixed(2)}</p>
          </div>
          <div className="card expense-card">
            <h3>Total Expense</h3>
            <p>₹ {totalExpense.toFixed(2)}</p>
          </div>
          <div className="card balance-card">
            <h3>Current Balance</h3>
            <p>₹ {balance.toFixed(2)}</p>
          </div>
        </div>

        {/* Charts Section */}
        {transactions.length > 0 && (
          <div className="charts-section">

            {/* Pie Chart - Expense by Category */}
            {pieData.length > 0 && (
              <div className="chart-box">
                <h3>Expense by Category</h3>
                <ResponsiveContainer width="100%" height={280}>
                  <PieChart>
                    <Pie
                      data={pieData}
                      dataKey="value"
                      nameKey="name"
                      cx="50%"
                      cy="50%"
                      outerRadius={90}
                      label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                    >
                      {pieData.map((entry, index) => (
                        <Cell key={index} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(value) => `₹${value}`} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            )}

            {/* Bar Chart - Monthly Income vs Expense */}
            {barData.length > 0 && (
              <div className="chart-box">
                <h3>Monthly Income vs Expense</h3>
                <ResponsiveContainer width="100%" height={280}>
                  <BarChart data={barData} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="month" tick={{ fontSize: 12 }} />
                    <YAxis tick={{ fontSize: 12 }} />
                    <Tooltip formatter={(value) => `₹${value.toFixed(2)}`} />
                    <Legend />
                    <Bar dataKey="income" fill="#4caf50" name="Income" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="expense" fill="#f44336" name="Expense" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            )}

          </div>
        )}

        {/* Action Buttons Row */}
        <div className="add-btn-row">
          <button
            className="add-transaction-btn"
            onClick={() => setShowForm(!showForm)}
          >
            {showForm ? 'Cancel' : '+ Add Transaction'}
          </button>
          <button
            className="export-csv-btn"
            onClick={handleExportCSV}
            disabled={csvLoading}
          >
            {csvLoading ? 'Exporting...' : '⬇ Export CSV'}
          </button>
        </div>

        {/* Show form only when button is clicked */}
        {showForm && (
          <TransactionForm onTransactionAdded={handleTransactionAdded} />
        )}

        {/* Recent Transactions */}
        <TransactionList
          transactions={recentTransactions}
          onDelete={handleDelete}
          heading="Recent Transactions"
        />

      </div>
    </div>
  );
}

export default Dashboard;
